    constructor(C _c) { c = _c; }

    // single public function with inputs to drive contract
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // read initial credit via the auto-generated getter: credit(address)
        uint creditBefore = c.credit(address(this));

        // perform a deposit to set up state (may be zero)
        c.deposit{value: depositAmount}();

        // read credit after deposit
        uint creditAfterDeposit = c.credit(address(this));

        // perform withdrawAll optionally, capturing whether it reverted
        bool withdrewReverted;
        if (doWithdraw) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            withdrewReverted = false;
        }

        // read final credit
        uint creditFinal = c.credit(address(this));

        // General rule asserting: deposit increases credit by depositAmount; and withdrawAll either sets credit to 0 if it succeeded, or leaves credit unchanged if it reverted (or was not called)
        assert(
            // deposit effect: creditAfterDeposit == creditBefore + depositAmount
            creditAfterDeposit == creditBefore + depositAmount
            &&
            // if withdrawAll was called and did not revert, final credit must be zero
            ((doWithdraw && !withdrewReverted) ? creditFinal == 0 : true)
            &&
            // if withdrawAll was called and reverted, final credit equals creditAfterDeposit
            ((doWithdraw && withdrewReverted) ? creditFinal == creditAfterDeposit : true)
        );
    }

    receive() external payable {}
