contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take an arbitrary prior deposit amount to set up credit,
    // then call withdrawAll and assert it does not increase contract balance or recorded credit
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");

        // set up: deposit some Ether into c to create nonzero credit for this contract
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // observe before-values via public surface
        uint beforeContractBalance = address(c).balance;
        // credit getter is not present in C (credit is private), so we observe by attempting to deposit zero
        // but credit mapping is not public; instead we rely on that deposit increased balance and that withdrawAll
        // should not increase address(c).balance nor any public observable credit. Since credit mapping is not
        // public, we use the fact that address(c).balance is observable and that withdrawAll should not increase it.

        // make the call and record whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

