    // depositAmount: how much to send to c; callWithdraw: whether to call withdrawAll
    function run(uint depositAmount, bool callWithdraw) public payable {
        // ensure this test contract can fund the deposit call
        require(address(this).balance >= depositAmount);

        // observe c balance before any actions
        uint beforeC = address(c).balance;

        // perform deposit on c if requested
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // observe c balance after deposit
        uint afterDepositC = address(c).balance;

        // Sanity: afterDepositC should equal beforeC + depositAmount
        // (we can't assert here because we must end with exactly one assert at the end)

        // attempt withdrawAll if requested and record whether it reverted
        bool withdrewReverted;
        if (callWithdraw) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            withdrewReverted = true; // treat as not-successful withdraw for the assertion shape
        }

        // observe c balance after withdraw attempt
        uint afterAllC = address(c).balance;

        // observe this contract balance change (it may have increased if withdraw succeeded)
        // Note: address(this).balance includes remaining Ether; we compute the delta relative to before deposit
        uint thisBalanceAfter = address(this).balance;

        // The single general rule asserted below:
        // If we performed deposit of depositAmount then either:
        //  - withdrawAll was not called or it reverted, in which case address(c).balance == afterDepositC (unchanged) and this contract's balance did not increase because of a successful withdraw;
        //  - or withdrawAll was called and succeeded, in which case address(c).balance decreased by exactly depositAmount (afterDepositC - afterAllC == depositAmount) and this contract's balance increased by exactly depositAmount (thisBalanceAfter + afterAllC == beforeC + depositAmount + (thisBalanceAfter - (beforeC - beforeC)) but simplified below).
        // We express the rule using observable balances only.

        assert(
            // If no withdraw was attempted (callWithdraw==false) treat as the first case: balances unchanged from afterDepositC
            (!callWithdraw && afterAllC == afterDepositC) ||
            (
                // If withdraw was attempted, then either it reverted and balances stayed as afterDeposit,
                (callWithdraw && withdrewReverted && afterAllC == afterDepositC)
                ||
                // or it succeeded and c's balance decreased by exactly depositAmount and this contract's balance increased by exactly depositAmount.
                (callWithdraw && !withdrewReverted && afterDepositC >= afterAllC && afterDepositC - afterAllC == depositAmount && thisBalanceAfter >= 0 && thisBalanceAfter - (address(this).balance - depositAmount) == depositAmount)
            )
        );
    }

    receive() external payable {}
}

